#define main strict_main
#include "lp2_class_clock_lexical.cpp"
#undef main
using Reason=array<uint64_t,29>;
static bool propagate_explain(Dom&dom,Reason&why,const Constraint *cs,int k,uint64_t&fail){bool changed=true;while(changed){changed=false;uint32_t fixed=0;array<uint64_t,29> fwhy{};for(int r=0;r<29;++r){auto d=dom[r];if(__builtin_popcount(d)==1){int p=__builtin_ctz(d);if(fixed&d){fail=why[r]|fwhy[p];return false;}fixed|=d;fwhy[p]=why[r];}}for(int r=0;r<29;++r)if(__builtin_popcount(dom[r])>1){uint32_t v=dom[r]&~fixed;if(v!=dom[r]){for(uint32_t z=dom[r]&fixed;z;z&=z-1)why[r]|=fwhy[__builtin_ctz(z)];if(!v){fail=why[r];return false;}changed=true;dom[r]=v;}}for(int j=0;j<k;++j){auto [w,e,n]=cs[j];uint64_t reason=1ull<<j;for(int i=0;i<n;++i)reason|=why[w[i]];array<uint32_t,14>s{};bool any=false;for(auto&row:e->rows){bool ok=true;for(int i=0;i<n;++i)if(!(dom[w[i]]&(1u<<row[i]))){ok=false;break;}if(ok){any=true;for(int i=0;i<n;++i)s[i]|=1u<<row[i];}}if(!any){fail=reason;return false;}for(int i=0;i<n;++i){auto&d=dom[w[i]];uint32_t v=d&s[i];if(v!=d){why[w[i]]|=reason;if(!v){fail=why[w[i]];return false;}changed=true;d=v;}}}}return true;}
struct OovFound{uint32_t mask;int burn,omit;array<int,29>key;};
static bool solve_omit(const Constraint*cs,int k,int omit,bool hold,array<int,29>&key,uint64_t&nodes){Dom d;d.fill(FULL);if(hold)d[0]=1;Constraint kept[64];int l=0;uint32_t used=0;for(int j=0;j<k;++j)if(j!=omit){auto [w,e,n]=cs[j];if(!e)return false;for(int i=0;i<n;++i){d[w[i]]&=e->unary[i];if(!d[w[i]])return false;used|=1u<<w[i];}kept[l++]=cs[j];}return dfs(d,kept,l,used,key,nodes);}
int main(int argc,char**argv){if(argc<3)return 1;Lex lex(argv[1]);ifstream f(argv[2]);vector<string> ws;string w;while(f>>w)ws.push_back(w);assert(ws.size()<=64);bool hold=argc>3&&atoi(argv[3]);Tape t(ws,hold);vector<int> bits;for(uint32_t v=t.active&~(t.active&-t.active);v;v&=v-1)bits.push_back(__builtin_ctz(v));uint32_t total=1u<<bits.size(),limit=argc>4?min(total,uint32_t(strtoul(argv[4],nullptr,10))):total;vector<uint32_t>lo(1u<<min(size_t(14),bits.size())),hi(1u<<(bits.size()-min(size_t(14),bits.size())));for(uint32_t x=1;x<lo.size();++x)lo[x]=lo[x&(x-1)]|(1u<<bits[__builtin_ctz(x)]);for(uint32_t x=1;x<hi.size();++x)hi[x]=hi[x&(x-1)]|(1u<<bits[__builtin_ctz(x)+min(size_t(14),bits.size())]);uint64_t tried=0,solved=0,nodes=0,unary=0,cores=0;vector<OovFound>found;const auto start=chrono::steady_clock::now();cerr<<"lex "<<lex.n<<" n "<<t.n<<" masks "<<total<<"\n";
 #pragma omp parallel
 {uint64_t tr=0,so=0,nd=0,u=0,co=0;vector<OovFound>local;vector<uint8_t>out(t.n);Constraint cs[64];int offsets[64];
 #pragma omp for schedule(static)
 for(uint32_t x=0;x<limit;++x){uint32_t mask=lo[x&(lo.size()-1)]|hi[x>>min(size_t(14),bits.size())];int burn=t.inverse(mask,out.data());Dom d;d.fill(FULL);if(hold)d[0]=1;Reason why{};uint64_t core=0;int missing=-1,k=0;bool impossible=false;
 for(auto w:t.words){if(w.start<burn)continue;const uint8_t*v=out.data()+w.start;auto it=lex.p.find(signature(v,w.n));const Entry*e=it==lex.p.end()?nullptr:&it->second;cs[k]={v,e,w.n};offsets[k]=w.start;if(!e){if(missing>=0){impossible=true;break;}missing=k;}else if(!core){for(int j=0;j<w.n;++j){uint32_t v2=d[v[j]]&e->unary[j];if(v2!=d[v[j]]){why[v[j]]|=1ull<<k;d[v[j]]=v2;}if(!v2){core=why[v[j]];break;}}}k++;}
 if(impossible)continue;if(missing>=0){if(core&&!(core&(1ull<<missing)))continue;core=1ull<<missing;}else if(!core){u++;uint64_t fail=0;if(!propagate_explain(d,why,cs,k,fail))core=fail;else core=k==64?~0ull:(1ull<<k)-1;}if(!core)continue;co+=__builtin_popcountll(core);bool foundmask=false;for(uint64_t z=core;z;z&=z-1){int omit=__builtin_ctzll(z);tr++;array<int,29> key;if(solve_omit(cs,k,omit,hold,key,nd)){foundmask=true;if(local.size()<100000)local.push_back({mask,burn,offsets[omit],key});}}if(foundmask)so++;}
 #pragma omp critical
 {tried+=tr;solved+=so;nodes+=nd;unary+=u;cores+=co;found.insert(found.end(),local.begin(),local.end());}}
 cout<<"{\"hold\":"<<hold<<",\"tested\":"<<limit<<",\"total\":"<<total<<",\"unary\":"<<unary<<",\"cores\":"<<cores<<",\"omissionsTested\":"<<tried<<",\"nodes\":"<<nodes<<",\"solvedMasks\":"<<solved<<",\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<",\"found\":[";for(size_t i=0;i<found.size();++i){auto&f=found[i];cout<<(i?",":"")<<"["<<f.mask<<","<<f.burn<<","<<f.omit<<",[";for(int j=0;j<29;++j)cout<<(j?",":"")<<f.key[j];cout<<"]]";}cout<<"]}\n";
}
